layer.css:
[data-ryt="pitch"] { color: var(--ryt-muted); border-left: 3px solid rgb(208, 196, 168); border-radius: 0px; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji"; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.65; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 1.6px; padding-right: 16px; padding-bottom: 1.6px; padding-left: 16px; transition: background-color 0.15s, border-color 0.15s, color 0.15s, fill 0.15s, stroke 0.15s; border-top: none; border-right: none; border-bottom: none }
article[data-ryt="rec-card"] { border-bottom: 1px solid rgb(221, 211, 186); border-radius: 0px; transition: background-color 0.15s, border-color 0.15s, color 0.15s, fill 0.15s, stroke 0.15s; border-top: none; border-right: none; border-left: none }
[data-ryt="footer"] { color: var(--ryt-muted); border-top: 1px solid rgb(221, 211, 186); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-text); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: rgb(208, 196, 168); text-decoration-thickness: auto; text-underline-offset: 2px; transition: background-color 0.15s, border-color 0.15s, color 0.15s, fill 0.15s, stroke 0.15s }
[data-ryt="hero"] h1 { color: var(--ryt-text); font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji"; font-size: 32px; font-weight: 600; font-style: normal; line-height: 1.3; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.15s, border-color 0.15s, color 0.15s, fill 0.15s, stroke 0.15s }
[data-ryt="section"] > h2 { color: var(--ryt-text); border-radius: 0px; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji"; font-weight: 600; font-style: normal; line-height: 1.3; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.15s, border-color 0.15s, color 0.15s, fill 0.15s, stroke 0.15s }
[data-ryt="review"] { color: var(--ryt-muted); font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji"; font-size: 14.4px; font-weight: 400; font-style: normal; line-height: 1.65; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.15s, border-color 0.15s, color 0.15s, fill 0.15s, stroke 0.15s }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji"; font-size: 13.6px; font-weight: 400; font-style: normal; line-height: 1.65; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.15s, border-color 0.15s, color 0.15s, fill 0.15s, stroke 0.15s }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-radius: 0px; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji"; font-weight: 600; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.15s, border-color 0.15s, color 0.15s, fill 0.15s, stroke 0.15s }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji"; font-size: 16px; font-weight: 600; font-style: normal; line-height: 1.65; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.15s, border-color 0.15s, color 0.15s, fill 0.15s, stroke 0.15s }
[data-ryt="button"] { color: var(--ryt-text); background-color: rgb(240, 233, 218); border-top: 1px solid rgb(221, 211, 186); border-right: 1px solid rgb(221, 211, 186); border-bottom: 1px solid rgb(221, 211, 186); border-left: 1px solid rgb(221, 211, 186); border-radius: 6px; font-family: Arial; font-weight: 400; font-style: normal; line-height: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 1px; padding-right: 6px; padding-bottom: 1px; padding-left: 6px; transition: background-color 0.15s, border-color 0.15s, color 0.15s, fill 0.15s, stroke 0.15s }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif, "Apple Color Emoji", "Segoe UI Emoji"; font-size: 18.4px; font-weight: 600; font-style: normal; line-height: 1.3; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: background-color 0.15s, border-color 0.15s, color 0.15s, fill 0.15s, stroke 0.15s }
[data-ryt="brand"]:hover { color: #546935; text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: #3d3a34; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: #546935; text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: #546935; text-decoration-line: underline; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; text-decoration-color: currentcolor }
